DROP DATABASE IF EXISTS ours; CREATE DATABASE ours; USE ours;
CREATE TABLE creature_loot_template (Entry INT UNSIGNED, ItemType TINYINT, Item INT UNSIGNED, Chance FLOAT, QuestRequired TINYINT, LootMode SMALLINT UNSIGNED, GroupId TINYINT UNSIGNED, MinCount TINYINT UNSIGNED, MaxCount TINYINT UNSIGNED, Comment VARCHAR(255), KEY(Entry), KEY(Item));
CREATE TABLE reference_loot_template LIKE creature_loot_template;
CREATE TABLE skinning_loot_template LIKE creature_loot_template;
CREATE TABLE pickpocketing_loot_template LIKE creature_loot_template;
CREATE TABLE creature_template_difficulty (Entry INT UNSIGNED, DifficultyID TINYINT UNSIGNED, LevelScalingDeltaMin INT, LevelScalingDeltaMax INT, ContentTuningID INT, HealthScalingExpansion INT, HealthModifier FLOAT, ManaModifier FLOAT, ArmorModifier FLOAT, DamageModifier FLOAT, CreatureDifficultyID INT, TypeFlags BIGINT, TypeFlags2 BIGINT, TypeFlags3 BIGINT, LootID INT UNSIGNED, PickPocketLootID INT UNSIGNED, SkinLootID INT UNSIGNED, GoldMin INT UNSIGNED, GoldMax INT UNSIGNED, StaticFlags1 BIGINT, StaticFlags2 BIGINT, StaticFlags3 BIGINT, StaticFlags4 BIGINT, StaticFlags5 BIGINT, StaticFlags6 BIGINT, StaticFlags7 BIGINT, StaticFlags8 BIGINT, VerifiedBuild INT, PRIMARY KEY(Entry,DifficultyID));
CREATE TABLE conditions (SourceTypeOrReferenceId INT, SourceGroup INT UNSIGNED, SourceEntry INT, SourceId INT, ElseGroup INT UNSIGNED, ConditionTypeOrReference INT, ConditionTarget TINYINT UNSIGNED, ConditionValue1 INT UNSIGNED, ConditionValue2 INT UNSIGNED, ConditionValue3 INT UNSIGNED, ConditionStringValue1 VARCHAR(255), NegativeCondition TINYINT UNSIGNED, ErrorType INT UNSIGNED, ErrorTextId INT UNSIGNED, ScriptName CHAR(64), Comment VARCHAR(255), PRIMARY KEY (SourceTypeOrReferenceId,SourceGroup,SourceEntry,SourceId,ElseGroup,ConditionTypeOrReference,ConditionTarget,ConditionValue1,ConditionValue2,ConditionValue3));
